25	const BASIS = {
26	  DE: { praefix: "de", lang: "de-DE", ogLocale: "de_DE" },
27	  AT: { praefix: "at", lang: "de-AT", ogLocale: "de_AT" },
28	  CH: { praefix: "ch", lang: "de-CH", ogLocale: "de_CH" },
29	};
30	
31	export const LAENDER = Object.freeze(
32	  Object.fromEntries(
33	    LAND_CODES.map((code) => [
34	      code,
35	      Object.freeze({ code, ...BASIS[code], ...LAENDER_ANGABEN[code], waehrung: waehrungFuer(code), einstieg: `/${BASIS[code].praefix}` }),
36	    ]),
37	  ),
38	);
