40	/** "de" | "DE" | " at " → "DE" | "AT"; alles andere → null */
41	export function landCode(wert) {
42	  const s = typeof wert === "string" ? wert.trim().toUpperCase() : "";
43	  return LAND_CODES.includes(s) ? s : null;
44	}
45	
46	/** URL-Präfix ("de") → Ländercode ("DE"); nur exakt kleingeschriebene Präfixe sind gültig. */
47	export function landAusPraefix(praefix) {
48	  if (typeof praefix !== "string") return null;
49	  return LAND_CODES.find((c) => BASIS[c].praefix === praefix) || null;
50	}
