52	/** Länderinfo; unbekannt → null */
53	export const landInfo = (wert) => LAENDER[landCode(wert)] || null;
54	
55	/** Einstiegsseite eines Landes ("/de"); unbekannt → null */
56	export const einstiegPfad = (wert) => landInfo(wert)?.einstieg || null;
