62	//
63	// Schlüssel = Pfad OHNE Länderpräfix, so wie er vor dem Umzug hieß ("/rechner/pacht").
64	//   pfad("/rechner/pacht")            → "/de/rechner/pacht"
65	//   pfad("/flaechencheck", "AT")      → "/at/flaechencheck"
66	//   pfad("/rechner/pacht", "AT")      → "/de/rechner/pacht"   (fehlt in AT → DE-Seite, „gilt für Deutschland“)
67	//   pfad("/kontakt", "AT")            → "/kontakt"            (Stamm: nie ein Präfix)
68	//   pfad("/ratgeber/x")               → "/wissen/ratgeber/x"  (umbenannt, Stamm)
69	//   pfad("/de/rechner/pacht", "AT")   → "/de/rechner/pacht"   (schon aufgelöst: unverändert, idempotent)
70	// Query und Anker bleiben erhalten.
