72	import { abs } from "../../data/site.js";
73	import { LAENDER, PRAEFIX_MUSTER, einstiegPfad, landAusPraefix, landCode } from "./laender.js";
74	import { EINSTIEG, laenderFrei, laenderMitSeite, seiteFuer, stufe, vorhanden } from "./stufen.js";
75	import { nurPfad, umbenannt, zoneFuer } from "./zonen.js";
76	
77	const zerlege = (roh) => {
78	  const s = String(roh ?? "");
79	  const i = s.search(/[?#]/);
80	  return i < 0 ? [s, ""] : [s.slice(0, i), s.slice(i)];
81	};
82	
83	/** Pfad einer Seite in einem Land (ohne Prüfung, ob es sie dort gibt). */
84	export const landPfad = (schluessel, land) => `${LAENDER[land].einstieg}${schluessel === "/" ? "" : schluessel}`;
85	
86	/**
87	 * Ziel eines Links im Kontext eines Landes.
88	 * @returns {{ href: string, land: string|null, art: "land"|"anderesLand"|"einstieg"|"stamm"|"unbekannt", giltFuer: string|null }}
89	 *   art "anderesLand": Die Seite fehlt im gewünschten Land; der Link führt in das Land, für das sie gilt
90	 *   (giltFuer z. B. „für Deutschland“ – sichtbar neben dem Link anzeigen).
91	 */
92	export function ziel(schluesselRoh, land = "DE") {
93	  const [roh, rest] = zerlege(schluesselRoh);
94	  const wunsch = landCode(land) || "DE";
95	  if (PRAEFIX_MUSTER.test(roh)) return { href: roh + rest, land: landAusPraefix(roh.slice(1, 3)), art: "land", giltFuer: null };
96	  const p = nurPfad(roh);
97	  const neu = umbenannt(p);
98	  if (neu) return { href: neu + rest, land: null, art: "stamm", giltFuer: null };
99	  if (zoneFuer(p) !== "land") return { href: roh + rest, land: null, art: "stamm", giltFuer: null };
100	  const s = seiteFuer(p);
101	  if (!s) return { href: roh + rest, land: null, art: "unbekannt", giltFuer: null };
102	  if (vorhanden(p, wunsch)) return { href: landPfad(p, wunsch) + rest, land: wunsch, art: "land", giltFuer: null };
103	  const andere = laenderMitSeite(p);
104	  const ersatz = andere.includes("DE") ? "DE" : andere[0];
105	  if (ersatz) return { href: landPfad(p, ersatz) + rest, land: ersatz, art: "anderesLand", giltFuer: LAENDER[ersatz].fuerLand };
106	  // Seite ist in keinem Land freigegeben (z. B. CH-Regionsseite im gestuften Start): Einstieg ihres Landes
107	  const heimat = s.laender[0];
108	  return { href: einstiegPfad(heimat), land: heimat, art: "einstieg", giltFuer: LAENDER[heimat].fuerLand };
109	}
110	
111	/**
112	 * Link mit sichtbarem Länderhinweis: fehlt die Seite im Land, zeigt das Label „(gilt für Deutschland)“.
113	 * @returns {{ href: string, label: string, giltFuer: string|null }}
114	 */
115	export function linkFuer(schluessel, land, label) {
116	  const z = ziel(schluessel, land);
117	  return { href: z.href, label: z.giltFuer ? `${label} (gilt ${z.giltFuer})` : label, giltFuer: z.giltFuer };
118	}
119	
120	/** Link-Ziel als String (siehe ziel()). Standardland DE. */
121	export const pfad = (schluessel, land = "DE") => ziel(schluessel, land).href;
122	
123	/**
124	 * Wo befindet sich ein (aufgelöster) Pfad?
125	 * @returns {{ land: string|null, schluessel: string, zone: string }}
126	 *   schluessel: Pfad ohne Länderpräfix ("" = Einstiegsseite des Landes)
127	 */
128	export function landAusPfad(pathname) {
129	  const p = nurPfad(pathname);
130	  const m = PRAEFIX_MUSTER.exec(p);
131	  if (m) {
132	    const rest = p.slice(m[0].length);
133	    return { land: landAusPraefix(m[1]), schluessel: rest === "/" ? EINSTIEG : rest, zone: "land" };
134	  }
135	  return { land: null, schluessel: p, zone: zoneFuer(p) };
136	}
137	
138	/**
139	 * Länderwechsler: Entsprechung der aktuellen Seite im Zielland, sonst dessen Einstieg.
140	 * @returns {{ href: string, art: "entsprechung"|"einstieg" }}
141	 */
142	export function entsprechung(pathname, zielLand) {
143	  const l = landCode(zielLand) || "DE";
144	  const { schluessel, zone } = landAusPfad(pathname);
145	  if (zone === "land" && vorhanden(schluessel, l)) return { href: landPfad(schluessel, l), art: "entsprechung" };
146	  return { href: einstiegPfad(l), art: "einstieg" };
147	}
148	
149	/**
150	 * hreflang-Cluster einer Seite der Länderzonen: alle Länder mit freigegebenem Inhalt + x-default.
151	 * x-default = DE-Fassung, wenn es sie gibt, sonst die erste freigegebene.
152	 * Bidirektional per Konstruktion: Alle Mitglieder eines Clusters liefern dieselbe Tabelle.
153	 * @returns {Record<string,string>} { "de-DE": url, "de-AT": url, "x-default": url } oder {} ohne Freigabe
154	 */
155	export function hreflang(schluessel) {
156	  const frei = laenderFrei(schluessel);
157	  if (!frei.length) return {};
158	  const tabelle = {};
159	  for (const l of frei) tabelle[LAENDER[l].lang] = abs(landPfad(schluessel, l));
160	  tabelle["x-default"] = abs(landPfad(schluessel, frei.includes("DE") ? "DE" : frei[0]));
161	  return tabelle;
162	}
163	
164	/**
165	 * Metadaten-Feld `alternates` (Next.js) für eine Seite.
166	 *  - Länderzone: canonical auf die eigene Länder-URL, languages = hreflang-Cluster
167	 *    (nur wenn die Seite in diesem Land freigegeben ist; „in Vorbereitung“ → nur canonical).
168	 *  - Stamm/ohne Präfix: canonical auf den Pfad selbst, nie ein Präfix; languages optional
169	 *    (z. B. das DE/EN-Paar aus src/components/En/sprachpaare.js).
170	 */
171	export function alternates(schluessel, land = "DE", { languages } = {}) {
172	  const p = schluessel === EINSTIEG ? EINSTIEG : nurPfad(schluessel);
173	  const l = landCode(land) || "DE";
174	  if (p !== EINSTIEG && zoneFuer(p) !== "land") {
175	    return { canonical: abs(p), ...(languages ? { languages } : {}) };
176	  }
177	  const canonical = abs(landPfad(p, l));
178	  if (stufe(p, l) !== "frei") return { canonical };
179	  return { canonical, languages: hreflang(p) };
180	}
181	
182	/** og:locale je Land ("de_AT") */
183	export const ogLocale = (land) => LAENDER[landCode(land) || "DE"].ogLocale;
184	
185	/** <html lang> je Land ("de-AT") */
186	export const htmlLang = (land) => LAENDER[landCode(land) || "DE"].lang;
