189	// src/lib/land/seite.js – Bausteine für Seiten der Länderzonen (Server, nutzt next/navigation)
190	//
191	// Getrennt von index.js, damit node:test, next.config.mjs und Client-Komponenten die reine
192	// Länderlogik ohne Next-Server-Funktionen laden können.
193	//
194	// Jede Seite unter src/app/(laender)/[land]/… ruft am Anfang
195	//   const { land } = await landDerSeite(params, "/rechner/pacht");
196	// und exportiert
