198	// Nicht freigegebene Kombinationen (stufen.js) enden in notFound() → 404.
199	// Ein Test (src/lib/land/routen.test.mjs) prüft, dass jede Route genau ihren Schlüssel nutzt.
200	
201	import { notFound } from "next/navigation";
202	import { landAusPraefix } from "./laender.js";
203	import { alternates, ogLocale } from "./pfad.js";
204	import { stufe } from "./stufen.js";
205	
206	/**
207	 * Land aus der Route prüfen. 404, wenn das Präfix unbekannt oder die Seite im Land nicht
208	 * freigegeben ist.
209	 * @param {Promise<{land: string}>|{land: string}} params
210	 * @param {string | ((p: object) => string)} schluessel Pfad ohne Präfix (bei dynamischen Routen aus params)
211	 * @returns {Promise<{ land: "DE"|"AT"|"CH", stufe: "frei"|"vorbereitung", schluessel: string }>}
212	 */
213	export async function landDerSeite(params, schluessel) {
214	  const p = (await params) || {};
215	  const land = landAusPraefix(p.land);
216	  const konkret = typeof schluessel === "function" ? schluessel(p) : schluessel;
217	  const st = land ? stufe(konkret, land) : null;
218	  if (!st) notFound();
219	  return { land, stufe: st, schluessel: konkret };
220	}
221	
222	/**
223	 * generateMetadata für eine Seite der Länderzonen: übernimmt die Basis-Metadaten der Seite und
224	 * setzt canonical, hreflang (alternates), og:url und og:locale je Land. „In Vorbereitung“ → noindex.
225	 * @param {string | ((p: object) => string)} schluessel
226	 * @param {object | ((land: string, p: object) => object|Promise<object>)} basis
227	 */
228	export function landMetadata(schluessel, basis) {
229	  return async function generateMetadata({ params }) {
230	    const p = (await params) || {};
231	    const land = landAusPraefix(p.land) || "DE";
232	    const konkret = typeof schluessel === "function" ? schluessel(p) : schluessel;
233	    const b = (typeof basis === "function" ? await basis(land, p) : basis) || {};
234	    const a = alternates(konkret, land);
235	    const st = stufe(konkret, land);
236	    return {
237	      ...b,
238	      alternates: { ...(b.alternates || {}), ...a },
239	      ...(b.openGraph ? { openGraph: { ...b.openGraph, url: a.canonical, locale: ogLocale(land) } } : {}),
240	      ...(st === "vorbereitung" ? { robots: { index: false, follow: true } } : {}),
241	    };
242	  };
243	}
