  "/projektboerse/[slug]": { titel: "Exposé", dynamisch: true, sitemap: false },
  // Strom & Gemeinschaft
  "/virtuelles-kraftwerk": { titel: "Virtuelles Kraftwerk", prio: 0.8, freq: "monthly" },
  "/reststrom": { titel: "Reststrom-Pool", prio: 0.8, freq: "monthly" },
