"use client";

// Link, der im Land der Seite bleibt (Ländermodell): auf /at/… zeigt href="/rechner/pacht" auf
// /at/rechner/pacht, auf der gemeinsamen Seite bleibt es /rechner/pacht. Pfade ohne
// Länderfassung (Portal, Login, /en …), externe Links und Anker bleiben unverändert;
// ausdrücklich gesetzte Präfixe ("/at/…") ebenso.
// Ersetzt `next/link` in allen öffentlichen Komponenten (gleiche Props, gleiches <a>).

import NextLink from "next/link";
import { forwardRef } from "react";
import { PRAEFIX_MUSTER, pfad } from "@/lib/land";
import { useSeitenLand } from "./LandKontext";

/** href im Land der Seite auflösen (String oder UrlObject). */
export function useLandHref(href) {
  const land = useSeitenLand();
  return landHref(href, land);
}

export function landHref(href, land) {
  if (typeof href === "string") return PRAEFIX_MUSTER.test(href) ? href : pfad(href, land);
  if (href && typeof href === "object" && typeof href.pathname === "string" && !PRAEFIX_MUSTER.test(href.pathname)) {
    return { ...href, pathname: pfad(href.pathname, land) };
  }
  return href;
}

const Link = forwardRef(function Link({ href, ...rest }, ref) {
  const ziel = useLandHref(href);
  return <NextLink ref={ref} href={ziel} {...rest} />;
});

export default Link;

