import { readFileSync, writeFileSync } from "node:fs";
const APP = "C:/Users/SALEADMIN/Downloads/Oekoinvest-Web/src/app/(stamm)";
const IMPORT = 'import { seitenLand, seitenMetadata } from "@/lib/land/seite";';
for (const k of Object.keys(SEITEN)) {
  if (SEITEN[k].dynamisch) continue;
  const f = `${APP}${k === "/" ? "" : k}/page.js`;
  let q = readFileSync(f, "utf8");
  const vorher = q;
  if (/landDerSeite\(/.test(q)) {
    q = q.replace(/import \{ landDerSeite, landMetadata \} from "@\/lib\/land\/seite";/, IMPORT);
