    q = q.replace(/^(\s*)const \{ land \} = await landDerSeite\(params, [^)]*\);/m, "$1const land = await seitenLand(params);");
    q = q.replace(/landMetadata\(/g, "seitenMetadata(");
  } else if (/export const metadata\b/.test(q)) {
    q = q.replace(/export const metadata\b/, "const metadata");
    // Import nach dem letzten Import einfügen
    const imports = [...q.matchAll(/^import [^;]+;\s*$/gm)];
    const letzter = imports[imports.length - 1];
    const pos = letzter.index + letzter[0].length;
    q = q.slice(0, pos) + "\n" + IMPORT + q.slice(pos);
    // Default-Export: params ergänzen, async, seitenLand als erste Anweisung
    const m = q.match(/export default (async )?function (\w*)\(([^)]*)\)\s*\{/);
    if (!m) throw new Error("kein default " + k);
    let args = m[3].trim();
    if (!args) args = "{ params }";
    else if (/^\{\s*searchParams\s*\}$/.test(args)) args = "{ params, searchParams }";
    else throw new Error("Signatur " + k + ": " + args);
    const neu = `export default async function ${m[2]}(${args}) {\n  await seitenLand(params);`;
    q = q.replace(m[0], neu);
    q = q.trimEnd() + `\n\nexport const generateMetadata = seitenMetadata(${JSON.stringify(k)}, metadata);\n`;
  }
  if (q !== vorher) { writeFileSync(f, q); console.log("umgebaut", k); }
  if (/landDerSeite|landMetadata/.test(q)) console.log("  REST", k);
}
EOF
