  unternehmen: { pfad: "/unternehmen", label: "Über uns" },
  kontakt: { pfad: "/kontakt", label: "Kontakt" },
};

/**
 * Länderrouting aktiv (Welle 2): Ziele werden je Land über src/lib/land aufgelöst. Fehlt eine Seite im Land, führt
